        :type quiet: List[int]
        :rtype: List[int]
        """
        n = len(quiet)
        graph = collections.defaultdict(list)
        for u, v in richer:
            graph[v].append(u)

        answer = [-1] * n

        def dfs(person):
            if answer[person] >= 0:
                return answer[person]
            answer[person] = person
            for neighbor in graph[person]:
                if quiet[answer[person]] > quiet[dfs(neighbor)]:
                    answer[person] = answer[neighbor]
